class Solution {
    public int getLucky(String s, int k) {
        StringBuilder numeric = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            numeric.append(s.charAt(i) - 'a' + 1);
        }

        String current = numeric.toString();
        int answer = 0;
        for (int round = 0; round < k; round++) {
            answer = 0;
            for (int i = 0; i < current.length(); i++) {
                answer += current.charAt(i) - '0';
            }
            current = String.valueOf(answer);
        }
        return answer;
    }
}

class Solution {
    public int getLucky(String s, int k) {
        int value = 0;
        for (int i = 0; i < s.length(); i++) {
            int position = s.charAt(i) - 'a' + 1;
            value += position / 10 + position % 10;
        }

        for (int round = 1; round < k; round++) {
            value = digitSum(value);
        }
        return value;
    }

    private int digitSum(int value) {
        int total = 0;
        while (value > 0) {
            total += value % 10;
            value /= 10;
        }
        return total;
    }
}

class Solution {
    public int getLucky(String s, int k) {
        int first = firstDigitSum(s, 0);
        return transform(first, k - 1);
    }

    private int firstDigitSum(String s, int index) {
        if (index == s.length()) {
            return 0;
        }
        int position = s.charAt(index) - 'a' + 1;
        return position / 10 + position % 10 + firstDigitSum(s, index + 1);
    }

    private int transform(int value, int remaining) {
        if (remaining == 0) {
            return value;
        }
        return transform(digitSum(value), remaining - 1);
    }

    private int digitSum(int value) {
        int total = 0;
        while (value > 0) {
            total += value % 10;
            value /= 10;
        }
        return total;
    }
}

class Solution {
    public int getLucky(String s, int k) {
        int value = 0;
        for (int i = 0; i < s.length(); i++) {
            int position = s.charAt(i) - 'a' + 1;
            value += position / 10 + position % 10;
        }

        if (k == 1) {
            return value;
        }
        value = digitSum(value);
        if (k == 2) {
            return value;
        }
        return 1 + (value - 1) % 9;
    }

    private int digitSum(int value) {
        int total = 0;
        while (value > 0) {
            total += value % 10;
            value /= 10;
        }
        return total;
    }
}
